const reclaimWhatsAppOutbox = `-- name: ReclaimWhatsAppOutbox :execrows
UPDATE whatsapp_outbox
SET status = 'queued', not_before = $1, claimed_at = NULL,
    last_error = 'gateway terputus saat mengirim'
WHERE workspace_id = $2
  AND status = 'sending'
  AND claimed_at < $3
`

type ReclaimWhatsAppOutboxParams struct {
	NotBefore   time.Time
	WorkspaceID uuid.UUID
	OlderThan   *time.Time
}

// A gateway killed mid-send leaves messages in `sending`. They go back to the
// queue rather than sitting there forever: the send either happened or it did
// not, and a duplicate is worse than a delay, so the attempt is spent and the
// message waits.
func (q *Queries) ReclaimWhatsAppOutbox(ctx context.Context, arg ReclaimWhatsAppOutboxParams) (int64, error) {
	result, err := q.db.Exec(ctx, reclaimWhatsAppOutbox, arg.NotBefore, arg.WorkspaceID, arg.OlderThan)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

